import os # Bound training CPU usage during concurrent native verification.
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1' # Keep this small prototype to one numerical thread.
import json,hashlib,csv,copy,time # Record real training, splits and evidence ownership.
from pathlib import Path # Resolve stable repository and output paths.
import numpy as np # Transform actual native contact labels into physical state coordinates.
import torch # Train actual neural residual state predictors locally.
from torch import nn # Define the explicitly low-dimensional learned state map.
import matplotlib # Render scientific results from actual independent rollouts.
matplotlib.use('Agg') # Avoid display dependencies.
import matplotlib.pyplot as plt # Plot independent prediction and reference histories.
ROOT=Path(__file__).resolve().parents[2]/'build/local-contact-20261024';OUT=ROOT/'contact-operator';OUT.mkdir(exist_ok=True);torch.set_num_threads(1) # Isolate prototype artifacts from original solver evidence.
SPLIT={'train':['baseline_mu03_p10','mu02_p10_verified','mu03_p05','mu03_p20'],'validation':['refined_mu03_p10'],'test':['mu04_p10','stiff_mu03_p10']};AREA=5000.;G=200000./2.6;H=10. # Declare whole-case splits and exact specimen constants before training.
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest() # Fingerprint actual input, weights and output artifacts.
def load_data(): # Load only approved native cases and validate every original source receipt.
    with (ROOT/'path_labels.csv').open() as handle: records=list(csv.DictReader(handle)) # Read transparent solver-backed scalar labels.
    data={} # Keep each entire pressure/shear path independent.
    for group,names in SPLIT.items(): # Assign case ownership before extracting any frame samples.
        for name in names: # Preserve the full case as one split unit.
            meta=json.loads((ROOT/name/'metadata.json').read_text());receipt=json.loads((ROOT/name/'receipt.json').read_text());assert all(sha(ROOT/name/file)==digest for file,digest in receipt['files'].items()) # Reject modified or truncated native evidence.
            rows=sorted([{key:float(value) for key,value in r.items() if key!='case'} for r in records if r['case']==name],key=lambda r:r['time']);assert len(rows)==48 and rows[-1]['time']==4. # Require the complete accepted four-stage load path.
            control=[];targets=[];previous_ux=0.;previous_p=0. # Start each independent path from the known unloaded state.
            for r in rows: # Convert source values to dimensionless physical states without using test statistics.
                p=r['pressure_MPa'];mu=r['mu'];kn=meta['normal_stiffness_N_per_mm3'];kt=meta['stick_stiffness_N_per_mm3'];ux=r['ux_drive_mm'];bulk_compliance=H/G;scale=mu*p*bulk_compliance # Normalize shear strain by current friction capacity and known bulk compliance.
                control.append([p/10.,mu/.3,ux/.1,(ux-previous_ux)/.1,previous_p/max(p,1.e-12),1.e6/kn,1.e4/kt]);targets.append([r['normal_N']/(p*AREA),r['contact_fx_N']/(mu*p*AREA),r['penetration_max_mm']*kn/p,(ux-r['slave_mean_ux_mm'])/scale]);previous_ux=ux;previous_p=p # Store actual normal force, signed shear force, penetration and elastic slip lag.
            data[name]={'group':group,'metadata':meta,'rows':rows,'x':torch.tensor(control,dtype=torch.float32),'y':torch.tensor(targets,dtype=torch.float32)} # Retain full paths and provenance alongside normalized tensors.
    return data # Return only physically normalized native labels.
def prior(control,previous): # Build a transparent elastic-perfectly-plastic contact state baseline from prior predicted shear.
    p=control[:,0]*10.;mu=control[:,1]*.3;du=control[:,3]*.1;pressure_ratio=control[:,4];kt=1.e4/control[:,6];keff=1./(H/G+1./kt);old_shear=previous[:,1]*pressure_ratio;shear=torch.clamp(old_shear-keff*du/(mu*p),-1.,1.) # Increment a series bulk/contact tangential spring and cap it at Coulomb friction.
    normal=torch.ones_like(p);peak=1.+.6*mu*torch.abs(shear);lag=-shear # Supply an explicit force equilibrium prior, elementary moment-pressure estimate and elastic bulk lag.
    return torch.stack([normal,shear,peak,lag],dim=1) # Keep the baseline separately testable; no native labels enter this calculation.
class StateProxy(nn.Module): # Learn a bounded residual correction to a four-state physical baseline.
    def __init__(self): # Make a compact network appropriate to the small number of independent cases.
        super().__init__();self.net=nn.Sequential(nn.Linear(15,48),nn.Tanh(),nn.Linear(48,48),nn.Tanh(),nn.Linear(48,4));nn.init.zeros_(self.net[-1].weight);nn.init.zeros_(self.net[-1].bias) # Start at the explicit physical prior rather than a random contact response.
    def forward(self,control,previous): # Consume current controls and the immediately preceding predicted or reference state.
        base=prior(control,previous);features=torch.cat([control,previous,base],dim=1);residual=self.net(features);return base+residual*torch.tensor([.05,.15,.5,.5],device=control.device) # Predict normal force, signed shear, peak penetration and mean interface slip via normalized states.
def rollout(model,case,use_prior=False,project=False): # Evaluate an entire unseen path without teacher forcing or reference-state injection.
    previous=torch.zeros((1,4));predictions=[] # Reset history once at the physical unloaded initial state.
    for control in case['x']: # Advance through actual applied controls only.
        estimate=prior(control[None],previous) if use_prior else model(control[None],previous) # Use prior predictions recursively, never true test output as the next input.
        if project: estimate=torch.stack([torch.clamp(estimate[:,0],min=0.),torch.maximum(torch.minimum(estimate[:,1],torch.clamp(estimate[:,0],min=0.)),-torch.clamp(estimate[:,0],min=0.)),torch.clamp(estimate[:,2],min=0.),estimate[:,3]],dim=1) # Apply only explicit positivity/Coulomb projection for the separately reported hybrid variant.
        predictions.append(estimate);previous=estimate # Carry the complete four-dimensional predicted state into the next increment.
    return torch.cat(predictions,dim=0) # Return all closed-path predictions for independent evaluation.
def physical(case,normalized): # Decode normalized states into the same native physical quantities as the reference.
    v=np.asarray(normalized,dtype=float);controls=case['x'].numpy();p=controls[:,0]*10.;mu=controls[:,1]*.3;ux=controls[:,2]*.1;kn=case['metadata']['normal_stiffness_N_per_mm3'];return np.column_stack([v[:,0]*p*AREA,v[:,1]*mu*p*AREA,v[:,2]*p/kn,ux-v[:,3]*mu*p*H/G]) # Produce N, N, mm and mm respectively without calibrating on test data.
def metrics(case,normalized): # Measure true physical rollout error and constraints independently of training loss.
    predicted=physical(case,normalized);reference=np.asarray([[r['normal_N'],r['contact_fx_N'],r['penetration_max_mm'],r['slave_mean_ux_mm']] for r in case['rows']]);p=np.asarray([r['pressure_MPa'] for r in case['rows']]);mu=case['metadata']['mu'];denom=np.maximum(np.linalg.norm(reference,axis=0),1.e-30);relative=np.linalg.norm(predicted-reference,axis=0)/denom;cone=np.maximum(np.abs(predicted[:,1])-mu*np.maximum(predicted[:,0],0.),0.)/np.maximum(mu*p*AREA,1.);normal_balance=np.abs(predicted[:,0]-p*AREA)/(p*AREA);state_error=float(np.sqrt(np.mean((normalized-case['y'].numpy())**2))) # Compute actual force balance and unconstrained friction-cone excess.
    return {'relative_L2':dict(zip(['normal_force','signed_contact_shear','peak_penetration','mean_interface_slip'],map(float,relative))),'normalized_state_RMSE':state_error,'normal_balance_relative_max':float(normal_balance.max()),'friction_cone_excess_relative_max':float(cone.max()),'negative_normal_frames':int(np.sum(predicted[:,0]<0.)),'negative_penetration_frames':int(np.sum(predicted[:,2]<0.))},predicted,reference # Keep shape-scaled error distinct from pointwise physical violations.
def score(model,data): # Select checkpoints using only a completely held-out numerical-discretization case.
    with torch.no_grad(): return float(np.mean([torch.mean((rollout(model,data[name])-data[name]['y'])**2).item() for name in SPLIT['validation']])) # Never inspect independent test paths for checkpoint or hyperparameter selection.
def train(seed,data): # Train one independently initialized residual model with explicit autoregressive fine tuning.
    torch.manual_seed(seed);np.random.seed(seed);model=StateProxy();optimizer=torch.optim.Adam(model.parameters(),lr=.002);x=[];previous=[];y=[];history=[];best=float('inf');best_state=None;start=time.monotonic() # Initialize a reproducible actual optimization run.
    for name in SPLIT['train']: # Construct teacher-forced samples only from whole training paths.
        case=data[name];x.append(case['x']);previous.append(torch.cat([torch.zeros((1,4)),case['y'][:-1]],dim=0));y.append(case['y']) # Keep preceding states within their own case boundaries.
    x=torch.cat(x);previous=torch.cat(previous);y=torch.cat(y) # Use 192 actual training increments without random frame splitting.
    for epoch in range(1,1801): # Fit the residual state transition from real native labels.
        optimizer.zero_grad();prediction=model(x,previous);loss=torch.mean((prediction-y)**2)+.05*torch.mean(torch.relu(torch.abs(prediction[:,1])-prediction[:,0])**2);loss.backward();optimizer.step() # Train actual network weights with a soft Coulomb constraint penalty.
        if epoch%100==0: # Evaluate checkpoints at a fixed declared cadence.
            validation=score(model,data);history.append({'phase':'teacher_forcing','epoch':epoch,'train_loss':float(loss),'validation_rollout_mse':validation}) # Record real optimization and validation history.
            if validation<best: best=validation;best_state=copy.deepcopy(model.state_dict()) # Keep only validation-selected model weights.
    model.load_state_dict(best_state);optimizer=torch.optim.Adam(model.parameters(),lr=.0003) # Begin autoregressive training from the best one-step checkpoint.
    for epoch in range(1,241): # Reduce accumulated errors using complete training rollouts.
        optimizer.zero_grad();loss=sum(torch.mean((rollout(model,data[name])-data[name]['y'])**2) for name in SPLIT['train'])/len(SPLIT['train']);loss.backward();nn.utils.clip_grad_norm_(model.parameters(),5.);optimizer.step() # Backpropagate through full 48-step training histories only.
        if epoch%20==0: # Assess validation under exactly the final recursive inference procedure.
            validation=score(model,data);history.append({'phase':'autoregressive','epoch':epoch,'train_loss':float(loss),'validation_rollout_mse':validation}) # Retain the actual rolling training trajectory.
            if validation<best: best=validation;best_state=copy.deepcopy(model.state_dict()) # Select the final checkpoint without test feedback.
    model.load_state_dict(best_state);torch.save({'state_dict':best_state,'seed':seed,'split':SPLIT,'architecture':'15 -> 48 tanh -> 48 tanh -> 4 residual','normalization':'physical dimensionless features defined in contact_train.py'},OUT/f'seed_{seed}.pt');(OUT/f'seed_{seed}_history.json').write_text(json.dumps(history,indent=2)+'\n') # Persist actual trained weights and auditable learning history.
    result={'seed':seed,'training_seconds':time.monotonic()-start,'best_validation_rollout_mse':best,'cases':{}};predictions=[] # Keep independent results separate by seed and case.
    with torch.no_grad(): # Disable gradients for all final independent evaluations.
        for name,case in data.items(): # Report all split groups without pooling their identities.
            result['cases'][name]={'split':case['group']} # Make leakage checks visible in the output.
            for mode in ['raw','projected','prior_only']: # Compare learned raw, explicitly projected, and nonlearned physics baseline fairly.
                normalized=rollout(model,case,use_prior=mode=='prior_only',project=mode=='projected').numpy();measure,predicted,reference=metrics(case,normalized);result['cases'][name][mode]=measure # Quantify physical constraint behavior before and after projection.
                for i,row in enumerate(case['rows']): predictions.append({'seed':seed,'case':name,'split':case['group'],'mode':mode,'time':row['time'],'ux_drive_mm':row['ux_drive_mm'],**dict(zip(['pred_normal_N','pred_contact_fx_N','pred_peak_penetration_mm','pred_mean_slip_mm'],map(float,predicted[i]))),**dict(zip(['true_normal_N','true_contact_fx_N','true_peak_penetration_mm','true_mean_slip_mm'],map(float,reference[i])))}) # Save every actual reference and rolling prediction for audit.
    return result,predictions # Return evaluated trained models without claiming full-field operator performance.
def main(): # Complete two-seed training, independent tests and evidence packaging in one reproducible command.
    data=load_data();assert not any(set(SPLIT[a])&set(SPLIT[b]) for a,b in [('train','validation'),('train','test'),('validation','test')]);results=[];predictions=[] # Assert whole-case disjointness before fitting any model.
    for seed in [17,29]: # Execute at least two independently seeded training runs.
        result,rows=train(seed,data);results.append(result);predictions.extend(rows);print(json.dumps({'seed':seed,'training_seconds':result['training_seconds'],'test_raw':{name:result['cases'][name]['raw'] for name in SPLIT['test']}}),flush=True) # Expose actual independent errors rather than selected best-case claims.
    with (OUT/'rollout_predictions.csv').open('w',newline='') as handle: writer=csv.DictWriter(handle,fieldnames=list(predictions[0]));writer.writeheader();writer.writerows(predictions) # Preserve full paths for every seed and evaluation mode.
    report={'status':'trained_and_independently_tested_restricted_four_state_contact_proxy','model_scope':'Low-dimensional neural residual state surrogate; NOT a full-field neural operator, NOT a bridge joint capacity model.','split':SPLIT,'frame_counts':{group:sum(len(data[name]['rows']) for name in names) for group,names in SPLIT.items()},'heldout_meaning':{'validation':'same nominal physical parameters as baseline but an independently solved finer mesh; this is discretization holdout, not a new parameter regime','mu04_p10':'unseen friction coefficient 0.4, beyond training maximum 0.3','stiff_mu03_p10':'unseen normal and tangential penalty stiffnesses increased tenfold'},'input':'Current pressure, friction coefficient, imposed displacement and increment, pressure ratio, normal/tangent penalty compliance plus immediately preceding predicted Fn/Ft/peak penetration/mean slip state. All paths start from zero; no true test state is injected.','output':'Four scalar physical states: normal force N, signed contact shear N, peak penalty penetration mm, mean interface x displacement mm. Gap is negative penetration for this always-closed path; opening/reclosure is not tested.','prior':'Explicit series elastic shear spring plus Coulomb cap, uniform-pressure normal equilibrium, elementary moment peak-pressure estimate and elastic bulk shear lag. Neural network learns residuals; prior-only baseline is reported separately.','projection':'The separately reported projected rollout clips negative force/penetration and caps signed friction by mu*Fn. A zero projected cone violation is by construction and does not prove predictive accuracy.','training':{'seeds':[17,29],'teacher_forcing_epochs':1800,'autoregressive_epochs':240,'optimizer':'Adam','selection':'validation closed-rollout MSE only','test_used_for_training_or_selection':False},'limitations':['Only four independent training parameter cases; these tests do not establish generalization to arbitrary loading paths.','All seven paths share the same four-stage protocol; no independent loading-protocol test.','Hidden full friction integration-point histories are not observed; this four-state compression is not proven Markov-complete.','Mean slip and peak penetration are scalar summaries; there is no learned field or mesh-to-mesh neural operator here.','Force balance check is normal resultant balance against known applied pressure; no independent predicted nodal equilibrium field exists.','Local contact peak field lacks demonstrated mesh convergence; prototype errors inherit this label limitation.'],'runs':results,'source_hashes':{'path_labels.csv':sha(ROOT/'path_labels.csv'),'solver_report.json':sha(ROOT/'REPORT.json'),'training_code.py':sha(Path(__file__))}} # State the precise achieved scope and evidence limitations.
    (OUT/'summary.json').write_text(json.dumps(report,indent=2)+'\n');fig,axes=plt.subplots(2,2,figsize=(11,7),layout='constrained') # Save machine-readable evidence before plotting independent tests.
    for j,name in enumerate(SPLIT['test']): # Plot two independently held-out physical/numerical regimes.
        reference=[r for r in predictions if r['seed']==17 and r['case']==name and r['mode']=='raw'];axes[0,j].plot([r['time'] for r in reference],[r['true_contact_fx_N']/1000 for r in reference],'k-',label='CalculiX');axes[1,j].plot([r['time'] for r in reference],[r['true_peak_penetration_mm']*1000 for r in reference],'k-',label='CalculiX') # Preserve actual native reference paths.
        for seed in [17,29]: # Show seed variation without choosing a favorable test result.
            rows=[r for r in predictions if r['seed']==seed and r['case']==name and r['mode']=='raw'];axes[0,j].plot([r['time'] for r in rows],[r['pred_contact_fx_N']/1000 for r in rows],'--',label=f'raw seed {seed}');axes[1,j].plot([r['time'] for r in rows],[r['pred_peak_penetration_mm']*1000 for r in rows],'--',label=f'raw seed {seed}') # Plot genuine recursive prediction output.
        axes[0,j].set(title=name,ylabel='Signed contact shear [kN]');axes[1,j].set(xlabel='Load-path pseudo-time',ylabel='Peak penetration [micrometres]') # Keep small physical units explicit.
    for ax in axes.flat: ax.grid(alpha=.25);ax.legend(fontsize=8) # Make comparisons easy to audit visually.
    fig.savefig(OUT/'independent_rollout_tests.png',dpi=180);fig.savefig(OUT/'independent_rollout_tests.pdf');plt.close(fig);(OUT/'MANIFEST.json').write_text(json.dumps({p.name:sha(p) for p in OUT.iterdir() if p.is_file() and p.name!='MANIFEST.json'},indent=2)+'\n') # Finish with independently reproducible figures and exact artifact fingerprints.
if __name__=='__main__': main() # Perform actual training and independent evaluation when invoked.
